import assert from 'node:assert/strict';
import {
  createGame,
  board,
  currentPlayer,
  legalMoves,
  applyMove,
  status,
} from './engine.mjs';

const a = createGame();
const b = createGame();
assert.notEqual(a, b, 'createGame returns a fresh State each call');
assert.equal(a.cells, b.cells, 'both fresh games share the frozen empty board');
assert.deepEqual([...board(a)], Array(9).fill(null));
assert.equal(currentPlayer(a), 'X');

let s = createGame();
for (const cell of [0, 3, 1, 4, 2]) s = applyMove(s, cell);
assert.equal(status(s).over, true);
assert.equal(status(s).winner, 'X');
assert.equal(status(s).reason, 'line');
assert.deepEqual(status(s).line, [0, 1, 2]);
const ended = s;

const fresh = createGame();
assert.notEqual(fresh, ended);
assert.deepEqual([...board(fresh)], Array(9).fill(null), 'new game clears every Mark');
assert.equal(currentPlayer(fresh), 'X', 'new game sets X to move');
assert.equal(status(fresh).over, false, 'outcome does not bleed through');
assert.equal(status(fresh).winner, null);
assert.equal(status(fresh).reason, null);
assert.equal(status(fresh).line, null);
assert.deepEqual(legalMoves(fresh), [0, 1, 2, 3, 4, 5, 6, 7, 8]);
assert.deepEqual([...board(ended)], ['X', 'X', 'X', null, 'O', null, null, null, null], 'ended State not mutated');
assert.equal(Object.isFrozen(ended.cells), true);

console.log('engine seam verified: fresh, cleared, X-to-move, no bleed, immutable');

